# Task 3: Download, unzip, and load NYC 2020 NTA boundaries
load_nyc_nta &lt;- function() {
  dir.create("data/mp03", recursive = TRUE, showWarnings = FALSE)

  nta_zip &lt;- "data/mp03/nynta2020_shp.zip"
  nta_dir &lt;- "data/mp03/nynta2020_shp"
  nta_url &lt;- "https://s-media.nyc.gov/agencies/dcp/assets/files/zip/data-tools/bytes/neighborhood-tabulation-areas/nynta2020_26d.zip"

  if (!file.exists(nta_zip)) {
    download.file(nta_url, destfile = nta_zip, mode = "wb")
  }

  if (!dir.exists(nta_dir)) {
    unzip(nta_zip, exdir = nta_dir)
  }

  shp_file &lt;- list.files(nta_dir, pattern = "\\.shp$", full.names = TRUE, recursive = TRUE)[1]

  nyc_nta &lt;- read_sf(shp_file) |&gt;
    select(BoroCode, BoroName, CountyFIPS, NTA2020, NTAName, NTAType, geometry)

  return(nyc_nta)
}

