# Task 5: Download PLUTO
load_nyc_pluto &lt;- function() {
  dir.create("data/mp03", recursive = TRUE, showWarnings = FALSE)
  pluto_file &lt;- "data/mp03/nyc_pluto.csv"

  if (!file.exists(pluto_file)) {
    base_url &lt;- "https://data.cityofnewyork.us/resource/64uk-42ks.csv"
    select_cols &lt;- paste(
      c(
        "bbl", "borough", "bct2020", "landuse", "bldgclass",
        "unitsres", "unitstotal", "resarea", "officearea",
        "comarea", "bldgarea", "numfloors"
      ),
      collapse = ","
    )

    limit &lt;- 25000
    offset &lt;- 0
    pages &lt;- list()
    page_idx &lt;- 1

    repeat {
      resp &lt;- request(base_url) |&gt;
        req_url_query(
          `$select` = select_cols,
          `$order`  = "bbl",
          `$limit`  = format(limit, scientific = FALSE),
          `$offset` = format(offset, scientific = FALSE)
        ) |&gt;
        req_retry(max_tries = 10, backoff = ~ 3) |&gt;
        req_perform()

      chunk &lt;- read_csv(
        resp_body_string(resp),
        col_types = cols(.default = col_character()),
        show_col_types = FALSE
      )

      if (nrow(chunk) == 0) break

      pages[[page_idx]] &lt;- chunk
      if (nrow(chunk) &lt; limit) break

      offset &lt;- offset + limit
      page_idx &lt;- page_idx + 1
      Sys.sleep(0.5)
    }

    pluto_df &lt;- bind_rows(pages) |&gt;
      mutate(
        across(
          c(unitsres, unitstotal, resarea, officearea, comarea, bldgarea, numfloors),
          as.numeric
        )
      )

    write_csv(pluto_df, pluto_file)
  }

  read_csv(
    pluto_file,
    col_types = cols(
      bbl = col_character(),
      borough = col_character(),
      bct2020 = col_character(),
      landuse = col_character(),
      bldgclass = col_character(),
      .default = col_double()
    ),
    show_col_types = FALSE
  )
}

